data.Corefile:
.:53 {
	errors
	health {
	   lameduck 5s
	}
	ready
	rewrite name api.hub.kbh-troubleshooting.com ingress-nginx-controller.knime.svc.cluster.local
    rewrite name auth.hub.kbh-troubleshooting.com ingress-nginx-controller.knime.svc.cluster.local
    rewrite name storage.hub.kbh-troubleshooting.com ingress-nginx-controller.knime.svc.cluster.local
	kubernetes cluster.local in-addr.arpa ip6.arpa {
	   pods insecure
	   fallthrough in-addr.arpa ip6.arpa
	   ttl 30
	}
	prometheus :9153
	forward . /etc/resolv.conf {
	   max_concurrent 1000
	}
	cache 30
	loop
	reload
	loadbalance
}
